insert into public.entries (slug,name,category,summary,description,auth_mode,endpoint,docs_url,tags,status,pricing,input_format,output_format,capabilities,invocation_example,rate_limit,probe_url,source,reviewed_at)
values
('google-gemini-api','Google Gemini API','api','Gemini text, vision and embedding models.','Google Generative Language API: generateContent, streaming, embeddings and model listing for Gemini models.','API key (x-goog-api-key header or key query param)','https://generativelanguage.googleapis.com/v1beta/models','https://ai.google.dev/api/rest',array['llm','ai','embeddings'],'approved','freemium','application/json','application/json',array['generate_content','list_models','embed_content'],'curl -s -H "x-goog-api-key: $GEMINI_API_KEY" "https://generativelanguage.googleapis.com/v1beta/models"','Free tier is quota limited per model; paid tier raises RPM/TPM.','https://ai.google.dev/api/rest','curated',now()),
('openrouter-api','OpenRouter','api','One OpenAI-compatible endpoint for 300+ models.','Routes chat completions to many providers behind a single OpenAI-compatible API; model list and pricing are public.','Bearer API key','https://openrouter.ai/api/v1','https://openrouter.ai/docs/api-reference/overview',array['llm','ai','gateway'],'approved','usage-based','application/json','application/json',array['chat_completions','list_models','model_pricing'],'curl -s "https://openrouter.ai/api/v1/models"','Per-key rate limits tied to credit balance; /models is public.',null,'curated',now()),
('groq-api','Groq Cloud','api','Very low latency OpenAI-compatible inference.','OpenAI-compatible chat, audio and model endpoints served on Groq LPU hardware.','Bearer API key','https://api.groq.com/openai/v1','https://console.groq.com/docs/api-reference',array['llm','ai','low-latency'],'approved','freemium','application/json','application/json',array['chat_completions','list_models','transcriptions'],'curl -s -H "Authorization: Bearer $GROQ_API_KEY" "https://api.groq.com/openai/v1/models"','Free tier limited per model in requests/day and tokens/minute.','https://console.groq.com/docs/api-reference','curated',now()),
('mistral-api','Mistral AI','api','Mistral chat, embeddings and OCR models.','European LLM provider with chat completions, embeddings, function calling, OCR and fine-tuning endpoints.','Bearer API key','https://api.mistral.ai/v1','https://docs.mistral.ai/api/',array['llm','ai','embeddings'],'approved','usage-based','application/json','application/json',array['chat_completions','embeddings','list_models','ocr'],'curl -s -H "Authorization: Bearer $MISTRAL_API_KEY" "https://api.mistral.ai/v1/models"','Tier based requests/second and tokens/month limits.','https://docs.mistral.ai/api/','curated',now()),
('cohere-api','Cohere','api','Chat, embed and rerank endpoints.','Cohere v2 API: chat, embeddings and the rerank model often used to sort retrieval results for agents.','Bearer API key','https://api.cohere.com/v2','https://docs.cohere.com/reference/about',array['llm','embeddings','rerank'],'approved','freemium','application/json','application/json',array['chat','embed','rerank','list_models'],'curl -s -H "Authorization: Bearer $COHERE_API_KEY" "https://api.cohere.com/v2/models"','Trial keys are rate limited and not for production; production keys scale.',null,'curated',now()),
('perplexity-api','Perplexity Sonar API','api','Answers with live web citations.','Sonar models return grounded answers with source citations; OpenAI-compatible chat completions shape.','Bearer API key','https://api.perplexity.ai/chat/completions','https://docs.perplexity.ai/api-reference/chat-completions-post',array['search','llm','citations'],'approved','usage-based','application/json','application/json',array['chat_completions','web_search','citations'],'curl -s -X POST "https://api.perplexity.ai/chat/completions" -H "Authorization: Bearer $PPLX_API_KEY" -H "Content-Type: application/json" -d ''{"model":"sonar","messages":[{"role":"user","content":"hello"}]}''','Per-tier requests/minute; unauthenticated calls return 401.','https://docs.perplexity.ai/','curated',now()),
('telegram-bot-api','Telegram Bot API','api','Send and receive messages as a bot.','Full bot platform: send messages, files, keyboards, polls and receive updates via long polling or webhook.','Bot token in the URL path','https://api.telegram.org','https://core.telegram.org/bots/api',array['messaging','notifications','bots'],'approved','free','application/json','application/json',array['send_message','get_updates','set_webhook','send_document'],'curl -s "https://api.telegram.org/bot$TELEGRAM_BOT_TOKEN/getMe"','About 30 messages/second overall and 1 message/second per chat.','https://core.telegram.org/bots/api','curated',now()),
('gitlab-rest-api','GitLab REST API','api','Projects, issues, merge requests and pipelines.','GitLab v4 REST API for repositories, issues, merge requests, CI pipelines and releases; public project reads need no token.','Bearer personal or project access token (public reads need none)','https://gitlab.com/api/v4','https://docs.gitlab.com/ee/api/rest/',array['git','devops','ci'],'approved','freemium','query params','application/json',array['get_project','list_issues','merge_requests','pipelines'],'curl -s "https://gitlab.com/api/v4/projects/gitlab-org%2Fgitlab"','2000 requests/minute per user on gitlab.com for authenticated REST calls.',null,'curated',now()),
('ipinfo-api','IPinfo','api','Geolocation and network owner of an IP.','City, region, country, ASN and privacy flags for an IP address; small volumes work without a token.','Bearer token (optional at low volume)','https://ipinfo.io','https://ipinfo.io/developers',array['geo','network','enrichment'],'approved','freemium','path params','application/json',array['ip_lookup','asn_lookup','batch_lookup'],'curl -s "https://ipinfo.io/8.8.8.8/json"','50k requests/month on the free token; unauthenticated use is throttled.',null,'curated',now()),
('unsplash-api','Unsplash API','api','Search and fetch free stock photos.','Photo search, random photos, collections and download tracking for the Unsplash library.','Client-ID access key','https://api.unsplash.com','https://unsplash.com/documentation',array['images','media','search'],'approved','freemium','query params','application/json',array['search_photos','random_photo','get_photo','collections'],'curl -s -H "Authorization: Client-ID $UNSPLASH_ACCESS_KEY" "https://api.unsplash.com/photos/random"','50 requests/hour in demo mode, 5000/hour once the app is approved.','https://unsplash.com/documentation','curated',now());